insert into questions (id, topic, year_level, difficulty, question_text, options, correct_index, explanation, curriculum_code, is_published)
values
('c23dbf3e-78db-42f3-bd2b-03a47ef52aae', 'number_operations', 'grade_3', 'foundation', 'What is 47 + 36?', '["73","83","81","93"]'::jsonb, 1, 'Add the ones: 7 + 6 = 13. Write 3, carry 1. Add the tens: 4 + 3 + 1 = 8. Answer: 83.', 'AC9M3N04', true),
('39e52f17-8622-49bc-b73a-5cdecc3668ae', 'number_operations', 'grade_4', 'developing', 'What is 248 + 375?', '["613","623","533","600"]'::jsonb, 1, 'Adding column by column: ones 8+5=13 (carry 1), tens 4+7+1=12 (carry 1), hundreds 2+3+1=6. Answer: 623.', 'AC9M4N04', true),
('458f66e7-5d18-40f3-af46-16ff171e225f', 'number_operations', 'grade_5', 'developing', 'Calculate 15 × 24', '["340","360","380","350"]'::jsonb, 1, '15 × 24 = 15 × 20 + 15 × 4 = 300 + 60 = 360.', 'AC9M5N04', true),
('6c56f7ea-0f72-407b-a5b7-6cf68fe4ce6c', 'number_operations', 'grade_6', 'developing', 'What is ¾ + ½?', '["1","1¼","1½","¾"]'::jsonb, 1, 'Convert to common denominator: ¾ + 2⁄4 = 5⁄4 = 1¼.', 'AC9M6N04', true),
('96262ed4-eb11-4c6a-a91d-fe6a373063c9', 'number_operations', 'grade_6', 'proficient', 'What is 20% of 450?', '["80","90","100","85"]'::jsonb, 1, '20% = 20/100 = 1/5. 450 ÷ 5 = 90.', 'AC9M6N05', true),
('617d183d-8898-4592-9695-72582b0109bb', 'number_operations', 'year_7', 'developing', 'Express 0.35 as a fraction in simplest form', '["3/5","7/20","35/100","7/10"]'::jsonb, 1, '0.35 = 35/100. Simplify by dividing by 5: 7/20.', 'AC9M7N03', true),
('ac08bd38-3a7d-4b96-b583-ff63e763bb9c', 'number_operations', 'year_8', 'proficient', 'Calculate: −3 × (−4) + 2', '["10","14","−10","−14"]'::jsonb, 1, '−3 × −4 = +12. Then 12 + 2 = 14.', 'AC9M8N03', true),
('61a7eacb-c722-480d-92b1-edd7865d8250', 'algebra_functions', 'year_7', 'foundation', 'Solve: x + 7 = 15', '["x = 7","x = 8","x = 9","x = 22"]'::jsonb, 1, 'Subtract 7 from both sides: x = 15 − 7 = 8.', 'AC9M7A02', true),
('2d67f5a7-047c-4453-98f5-13a4a897d540', 'algebra_functions', 'year_7', 'developing', 'What is the next term in the sequence: 3, 7, 11, 15, ___?', '["17","18","19","20"]'::jsonb, 2, 'The common difference is +4. 15 + 4 = 19.', 'AC9M7A01', true),
('c8d6e78d-84e3-48e8-8778-634f0db174a4', 'algebra_functions', 'year_8', 'developing', 'Simplify: 4x + 3x − 2x', '["5x","9x","7x","x"]'::jsonb, 0, 'Collect like terms: (4 + 3 − 2)x = 5x.', 'AC9M8A01', true),
('f21ff070-d3d8-4e69-b9d1-cc965b53e1ff', 'algebra_functions', 'year_9', 'proficient', 'Factorise: x² − 9', '["(x+3)(x+3)","(x−3)(x+3)","(x−9)(x+1)","(x+9)(x−1)"]'::jsonb, 1, 'Difference of two squares: a² − b² = (a−b)(a+b). So x² − 9 = (x−3)(x+3).', 'AC9M9A01', true),
('98490cd9-b9c1-4b78-a692-4636eea71cbc', 'algebra_functions', 'year_10', 'proficient', 'If f(x) = 2x² − 3, what is f(−2)?', '["5","−11","−5","11"]'::jsonb, 0, 'f(−2) = 2(−2)² − 3 = 2(4) − 3 = 8 − 3 = 5.', 'AC9M10A02', true),
('a3227722-463c-4d3a-953e-dedf94ffa757', 'geometry_measurement', 'grade_4', 'foundation', 'What is the perimeter of a square with side length 7 cm?', '["14 cm","21 cm","28 cm","49 cm"]'::jsonb, 2, 'Perimeter of a square = 4 × side = 4 × 7 = 28 cm.', 'AC9M4M02', true),
('a3bcde8a-e33d-4304-9c05-59101e339834', 'geometry_measurement', 'grade_5', 'developing', 'Area of a rectangle: length 8 cm, width 5 cm', '["26 cm²","40 cm²","13 cm²","45 cm²"]'::jsonb, 1, 'Area = length × width = 8 × 5 = 40 cm².', 'AC9M5M02', true),
('bca5ead2-f1bb-40ef-a116-8b77635e58ab', 'geometry_measurement', 'grade_6', 'proficient', 'Volume of a cube with side length 4 cm?', '["16 cm³","48 cm³","64 cm³","12 cm³"]'::jsonb, 2, 'Volume of a cube = side³ = 4³ = 64 cm³.', 'AC9M6M02', true),
('fe66cdd3-5735-4593-893d-149840de519b', 'geometry_measurement', 'year_7', 'developing', 'Area of a circle with radius 5 cm? (use π ≈ 3.14)', '["78.5 cm²","31.4 cm²","15.7 cm²","157 cm²"]'::jsonb, 0, 'A = πr² = 3.14 × 5² = 3.14 × 25 = 78.5 cm².', 'AC9M7M02', true),
('248a22df-0128-4c1b-ae8c-b6c48148eeba', 'geometry_measurement', 'year_9', 'proficient', 'In a right triangle, legs are 6 cm and 8 cm. What is the hypotenuse?', '["10 cm","12 cm","14 cm","7 cm"]'::jsonb, 0, 'Pythagoras: c² = 6² + 8² = 36 + 64 = 100. c = √100 = 10 cm.', 'AC9M9M03', true),
('7fe9cb1e-c2f8-4b27-a07d-159bc4219368', 'statistics_probability', 'grade_4', 'foundation', 'What is the mode of: 2, 4, 4, 5, 6, 4, 7?', '["2","4","5","6"]'::jsonb, 1, 'The mode is the most frequent value. 4 appears 3 times.', 'AC9M4ST01', true),
('c2bbbfe9-28fb-4857-861d-f5050375b792', 'statistics_probability', 'grade_5', 'developing', 'Mean of: 4, 7, 9, 10, 5', '["6","7","8","9"]'::jsonb, 1, 'Sum = 4+7+9+10+5 = 35. Mean = 35 ÷ 5 = 7.', 'AC9M5ST01', true),
('0b6ec697-94fb-42c6-959f-6e7abc8cb892', 'statistics_probability', 'grade_6', 'developing', 'Median of: 3, 5, 7, 9, 11', '["5","7","9","6"]'::jsonb, 1, 'Data is already ordered. Middle value (3rd of 5) = 7.', 'AC9M6ST01', true),
('df773e2f-c2be-4735-bdef-ae4030e187a0', 'statistics_probability', 'year_7', 'developing', 'What is the probability of rolling a 6 on a fair die?', '["1/3","1/4","1/6","1/2"]'::jsonb, 2, 'There are 6 equally likely outcomes. P(6) = 1/6.', 'AC9M7P01', true),
('fb70f0b9-45af-44ca-a7d5-379f78d6917b', 'statistics_probability', 'year_8', 'proficient', 'Range of: 12, 7, 19, 3, 15', '["12","16","7","19"]'::jsonb, 1, 'Range = max − min = 19 − 3 = 16.', 'AC9M8ST01', true),
('4c9c48fc-ba92-47c2-b8e7-d85eee10b828', 'reading_comprehension', 'grade_3', 'foundation', 'Read: "Tom packed his bag and ran to catch the bus. He was late for school." Why did Tom run?', '["He wanted exercise","He was late for school","He lost his bag","He missed the bus"]'::jsonb, 1, 'The passage says Tom ''was late for school,'' which is why he ran to catch the bus.', 'AC9E3LY06', true),
('88176768-82e6-40f6-a4b6-e2a8449adfe7', 'reading_comprehension', 'grade_5', 'developing', 'Read: "Although it was raining, Maya decided to go for a walk because she loved the smell of wet earth." What is Maya''s motivation for going outside?', '["She had to walk the dog","She loved the smell of rain","She was late","She wanted to get wet"]'::jsonb, 1, 'The word ''because'' signals her reason: she loved the smell of wet earth.', 'AC9E5LY07', true),
('f32db62e-cfd9-4ce9-a39e-0bf06cb95bc2', 'reading_comprehension', 'grade_6', 'developing', 'In a story, a character who changes and grows over time is called a:', '["Static character","Dynamic character","Narrator","Antagonist"]'::jsonb, 1, 'A dynamic character undergoes meaningful internal change during the story.', 'AC9E6LE07', true),
('57e7176d-1784-41e5-b934-b008fe956f1a', 'reading_comprehension', 'year_7', 'proficient', 'Read: "The old bridge groaned under the weight of the truck, its timbers creaking like tired bones." This sentence mainly uses which literary device?', '["Simile","Metaphor","Onomatopoeia","Hyperbole"]'::jsonb, 0, '''Creaking like tired bones'' compares the bridge''s sound to bones using ''like'' — a simile.', 'AC9E7LE05', true),
('f8f0d371-501c-4e1e-8a34-ba7636d6558d', 'reading_comprehension', 'year_9', 'advanced', 'An author who writes with a critical or mocking tone about the flaws of society is using:', '["Satire","Elegy","Parody","Soliloquy"]'::jsonb, 0, 'Satire uses irony, humour, and exaggeration to criticise society''s flaws.', 'AC9E9LE04', true),
('13289b3d-55d7-4388-8289-12e944e75a28', 'grammar_punctuation', 'grade_3', 'foundation', 'Which sentence uses the correct punctuation?', '["Where is my hat","Where is my hat.","Where is my hat?","where is my hat?"]'::jsonb, 2, 'Questions must end with a question mark and start with a capital letter.', 'AC9E3LA05', true),
('b4e8d10c-3038-4248-acbf-99c71fe7dd11', 'grammar_punctuation', 'grade_4', 'developing', 'Choose the correctly punctuated sentence.', '["Its a sunny day.","It''s a sunny day.","Its'' a sunny day.","Its a sunny day"]'::jsonb, 1, '''It''s'' is the contraction of ''it is''. ''Its'' (no apostrophe) shows possession.', 'AC9E4LA06', true),
('50d57618-b6ac-4a40-9414-11fc145bebcb', 'grammar_punctuation', 'grade_6', 'proficient', 'Identify the sentence with correct subject-verb agreement.', '["The team are winning.","The team is winning.","The team am winning.","The team be winning."]'::jsonb, 1, '''Team'' is a collective noun treated as singular in Australian English, so it takes ''is''.', 'AC9E6LA07', true),
('44031c53-3fe9-401e-be48-ed1ff2ccc2bc', 'grammar_punctuation', 'year_7', 'developing', 'Which word correctly completes: ''Neither the students nor the teacher ___ ready.''', '["was","were","is","are"]'::jsonb, 0, 'With ''neither/nor'', the verb agrees with the nearer subject — ''teacher'' (singular), so ''was''.', 'AC9E7LA05', true),
('06ae62bf-37df-4c5e-a56e-ed9c1cf7512c', 'grammar_punctuation', 'year_8', 'proficient', 'Which sentence correctly uses a semicolon?', '["I like tea; however, I prefer coffee.","I like tea, however I prefer coffee.","I like tea; and coffee.","I like tea however; I prefer coffee."]'::jsonb, 0, 'A semicolon can join two related independent clauses, often before a conjunctive adverb like ''however''.', 'AC9E8LA06', true),
('d0787f9d-fc16-4824-bd33-9b5a9ce48d10', 'vocabulary', 'grade_3', 'foundation', 'Which word means the same as ''happy''?', '["Glad","Sad","Angry","Tired"]'::jsonb, 0, '''Glad'' is a synonym for ''happy'' — both describe feeling pleased.', 'AC9E3LA09', true),
('38223913-5840-4bd4-8f9d-1bbea56a700f', 'vocabulary', 'grade_5', 'developing', 'What is the antonym (opposite) of ''generous''?', '["Kind","Selfish","Wealthy","Helpful"]'::jsonb, 1, '''Selfish'' means the opposite of ''generous'', which means willing to give.', 'AC9E5LA10', true),
('ef89ac55-5590-45b9-8ca7-8a935961c8a9', 'vocabulary', 'grade_6', 'developing', 'The prefix ''un-'' in the word ''unhappy'' means:', '["Very","Again","Not","Before"]'::jsonb, 2, 'The prefix ''un-'' means ''not'', so ''unhappy'' means ''not happy''.', 'AC9E6LA09', true),
('96962a07-d84a-4489-b4b4-4324f88b2b26', 'vocabulary', 'year_7', 'proficient', 'Which word best fits: ''The detective''s ___ observation solved the case.''', '["meticulous","careless","hasty","vague"]'::jsonb, 0, '''Meticulous'' means very careful and precise, fitting a detective solving a case.', 'AC9E7LA10', true),
('bf750551-cf5e-491e-9e3c-eac4f1057ee0', 'vocabulary', 'year_9', 'advanced', '''Ubiquitous'' most nearly means:', '["Rare","Present everywhere","Ancient","Loud"]'::jsonb, 1, '''Ubiquitous'' describes something found everywhere or very common.', 'AC9E9LA08', true),
('5ca913e1-318e-47f6-b043-4719b7bb1540', 'life_science', 'grade_3', 'foundation', 'Which of these is a living thing?', '["Rock","Tree","Chair","Cloud"]'::jsonb, 1, 'Living things grow, reproduce, and need energy — a tree is alive; rocks, chairs and clouds are not.', 'AC9S3U01', true),
('9bf731e1-fa29-4479-92ed-ba7882e1b692', 'life_science', 'grade_5', 'developing', 'What is the main function of a plant''s roots?', '["Make food using sunlight","Absorb water and nutrients","Produce seeds","Release oxygen"]'::jsonb, 1, 'Roots anchor the plant and absorb water and nutrients from the soil.', 'AC9S5U01', true),
('12310b4f-6289-41b5-8379-2d52e086a163', 'life_science', 'grade_6', 'developing', 'Which organ pumps blood around the human body?', '["Lungs","Liver","Heart","Stomach"]'::jsonb, 2, 'The heart is a muscular organ that pumps blood through the circulatory system.', 'AC9S6U02', true),
('a7543b7a-a68d-4973-bed4-370427f0228d', 'life_science', 'year_7', 'proficient', 'In a food chain, what is the primary role of a producer?', '["Eats other animals","Makes its own food using sunlight","Decomposes dead matter","Hunts prey"]'::jsonb, 1, 'Producers, like plants, make their own food through photosynthesis.', 'AC9S7U03', true),
('75a77b8c-543b-4772-a94b-1f700d4c4f3f', 'life_science', 'year_9', 'advanced', 'Which process allows cells to divide and produce two genetically identical daughter cells?', '["Meiosis","Mitosis","Fertilisation","Osmosis"]'::jsonb, 1, 'Mitosis produces two genetically identical daughter cells for growth and repair.', 'AC9S9U03', true),
('2f9423e0-9e64-47f0-ba90-f0e31d32a1ff', 'physical_science', 'grade_4', 'foundation', 'What happens to water when it is heated to boiling point?', '["It freezes","It turns into gas","It turns into rock","It disappears forever"]'::jsonb, 1, 'At boiling point, water changes from a liquid to a gas (water vapour).', 'AC9S4U01', true),
('d7c1d9c5-c9de-4188-851b-fb10521c436b', 'physical_science', 'grade_6', 'developing', 'Which of these is a force that slows down moving objects?', '["Gravity","Friction","Magnetism","Light"]'::jsonb, 1, 'Friction acts opposite to motion between surfaces, slowing objects down.', 'AC9S6U01', true),
('b4135d64-f9bb-403b-8899-464791404fae', 'physical_science', 'year_7', 'developing', 'What is the unit used to measure electric current?', '["Volt","Watt","Ampere","Ohm"]'::jsonb, 2, 'Electric current is measured in amperes (amps), symbol A.', 'AC9S7U01', true),
('08c4487d-e0de-45dd-a475-9b23f8d3b6ee', 'physical_science', 'year_8', 'proficient', 'Which state of matter has a fixed volume but no fixed shape?', '["Solid","Liquid","Gas","Plasma"]'::jsonb, 1, 'A liquid takes the shape of its container but keeps a fixed volume.', 'AC9S8U01', true),
('fa75ee6b-7411-4dc0-8f24-9db75d523b3e', 'physical_science', 'year_10', 'advanced', 'According to Newton''s second law, force equals:', '["mass ÷ acceleration","mass × acceleration","mass + acceleration","acceleration ÷ mass"]'::jsonb, 1, 'Newton''s second law states F = m × a (force equals mass times acceleration).', 'AC9S10U03', true),
('5955cdef-1a18-49bc-867e-83772e0bb443', 'earth_space', 'grade_3', 'foundation', 'What causes day and night on Earth?', '["The Moon orbiting Earth","Earth spinning on its axis","The Sun moving around Earth","Clouds covering the Sun"]'::jsonb, 1, 'Earth rotates on its axis once every 24 hours, causing day and night.', 'AC9S3U02', true),
('c6fb52e0-4bff-4659-bb3d-5374d17ab882', 'earth_space', 'grade_5', 'developing', 'Which layer of the Earth is the hottest?', '["Crust","Mantle","Outer core","Inner core"]'::jsonb, 3, 'The inner core is the hottest layer, reaching temperatures similar to the Sun''s surface.', 'AC9S5U02', true),
('6eec1bb8-817f-4d8a-9cfe-f1fea7cc875b', 'earth_space', 'grade_6', 'developing', 'What is the main cause of the seasons on Earth?', '["Distance from the Sun changing a lot","The tilt of Earth''s axis","The Moon''s gravity","Ocean currents"]'::jsonb, 1, 'Earth''s axial tilt means different hemispheres receive more or less direct sunlight through the year, causing seasons.', 'AC9S6U03', true),
('5327c5a5-d566-472a-9c20-46d7b7130175', 'earth_space', 'year_8', 'proficient', 'Which type of rock forms from cooled magma or lava?', '["Sedimentary","Metamorphic","Igneous","Fossil"]'::jsonb, 2, 'Igneous rock forms when magma or lava cools and solidifies.', 'AC9S8U02', true),
('2a50a3c3-40ff-4e56-947a-394adc7cab21', 'earth_space', 'year_9', 'advanced', 'What is the primary evidence used to support the theory of plate tectonics?', '["Fossil records only","Matching coastlines, fossils, and rock strata across continents","Ocean temperature","Moon phases"]'::jsonb, 1, 'Matching coastlines, fossil distributions, and rock strata across continents provide strong evidence for plate tectonics.', 'AC9S9U04', true)
